$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$manifestPath=Join-Path $root 'port-changes.json';$m=Get-Content $manifestPath -Raw|ConvertFrom-Json
$targets=@(
 [pscustomobject]@{rel='content/logistics/packagerLink/LogisticallyLinkedClientHandler.java';changes=@([pscustomobject]@{from='import net.createmod.catnip.animation.AnimationTickHolder;';to='import com.simibubi.create.foundation.utility.AnimationTickHolder;'},[pscustomobject]@{from='import net.createmod.catnip.outliner.Outliner;';to='import com.simibubi.create.foundation.outliner.Outliner;'});status='Original linked-network selection outlines retained using the Fabric baseline AnimationTickHolder and Outliner.'},
 [pscustomobject]@{rel='content/logistics/packager/repackager/RepackagerBlockEntity.java';changes=@([pscustomobject]@{from='PackageItem.isPackage(resource)';to='PackageItem.isPackage(resource.toStack())'},[pscustomobject]@{from='PackageItem.getOrderId(resource)';to='PackageItem.getOrderId(resource.toStack())'});status='Original repackager transfer predicates retained with Fabric ItemVariant converted to its component-bearing ItemStack view.'},
 [pscustomobject]@{rel='content/logistics/packager/PackagerRenderer.java';changes=@([pscustomobject]@{from='.rotateYCenteredDegrees(AngleHelper.horizontalAngle(facing))';to='.rotateCentered(Direction.UP, AngleHelper.rad(AngleHelper.horizontalAngle(facing)))'},[pscustomobject]@{from='.rotateXCenteredDegrees(AngleHelper.verticalAngle(facing))';to='.rotateCentered(Direction.EAST, AngleHelper.rad(AngleHelper.verticalAngle(facing)))'},[pscustomobject]@{from='.rotateYCenteredDegrees(facing.toYRot())';to='.rotateCentered(Direction.UP, AngleHelper.rad(facing.toYRot()))'},[pscustomobject]@{from='.rotateYDegrees(facing.toYRot())';to='.rotateY(facing.toYRot())'});status='Original Packager hatch, tray and displayed-package animation retained; Fabric rotation APIs adapted.'}
)
foreach($t in $targets){$path=Join-Path $root "source/fabric/src/main/java/com/simibubi/create/$($t.rel)";$text=[IO.File]::ReadAllText($path);foreach($c in $t.changes){if(-not$text.Contains($c.from)){throw "Packager client anchor missing in $($t.rel): $($c.from)"};$text=$text.Replace($c.from,$c.to)};[IO.File]::WriteAllText($path,$text,[Text.UTF8Encoding]::new($false));$e=$m.files|Where-Object path -eq $t.rel;$e.changes=@($e.changes)+$t.changes;$e.status=$t.status};$m|ConvertTo-Json -Depth 20|Set-Content $manifestPath -Encoding utf8;Write-Output 'Adapted linked-client, repackager transfer and Packager renderer APIs.'
